{%- doc -%}
  Renders the blog post image block.

  @param {object} article - The article object
  @param {string} [image_sizes] - The responsive sizes value for this image (defaults to '100vw')
  @param {string} [image_loading] - The loading strategy for this image (defaults to 'eager')
  @param {string} [image_fetch_priority] - The fetch priority for this image (defaults to 'auto')
{%- enddoc -%}

{% liquid
  assign image = article.image
  assign block_settings = block.settings
  assign sizes = image_sizes | default: '100vw'
  assign loading = image_loading | default: 'eager'
  assign fetch_priority = image_fetch_priority | default: 'auto'

  if loading == 'lazy'
    assign sizes = 'auto, ' | append: sizes
  endif

  # Blog cards max out at 983px, so 2000px covers high-density displays.
  # resource-image.liquid and _blog-post-featured-image.liquid use larger widths for larger layouts.
  assign widths = '400, 640, 832, 1000, 1500, 2000'
  assign image_class = 'border-style blog-post-card__image blog-post-card__image--' | append: block_settings.height
%}

{%- capture image_border_style -%}
  {% render 'border-override', settings: block_settings %}
{%- endcapture -%}

<div
  class="blog-post-card__image-container"
  {{ block.shopify_attributes }}
>
  <a href="{{ article.url }}">
    {{
      image
      | image_url: width: 2000
      | image_tag:
        width: image.width,
        widths: widths,
        height: image.height,
        sizes: sizes,
        loading: loading,
        fetchpriority: fetch_priority,
        alt: image.alt,
        class: image_class,
        style: image_border_style
    }}
  </a>
</div>

{% stylesheet %}
  .blog-post-card__image {
    width: 100%;
    object-fit: cover;
    object-position: center center;
    height: calc(var(--blog-post-card-img-height) * var(--blog-post-card-scale));
  }

  .blog-post-card__image--small {
    --blog-post-card-img-height: 280px;
  }

  .blog-post-card__image--medium {
    --blog-post-card-img-height: 340px;
  }

  .blog-post-card__image--large {
    --blog-post-card-img-height: 400px;
  }
{% endstylesheet %}

