{%- assign block_index = section.blocks | find_index: 'id', block.id -%}

{%- liquid
  assign preview_image = block.settings.image_1
  if block.settings.media_type_1 == 'video'
    assign preview_image = block.settings.video_1.preview_image
  endif

  if block.settings.background_color != blank
    render 'contrast-override', background_color: block.settings.background_color, section_id: block.id, skip_contrast: true
  endif
-%}

<div
  role="tabpanel"
  ref="panels[]"
  id="Panel-{{ block.id }}-{{ section.id }}"
  aria-labelledby="Tab-{{ block.id }}-{{ section.id }}"
  tabindex="0"
  class="layered-slideshow__panel {% if section.settings.drop_shadow %}layered-slideshow__panel--drop-shadow{% endif %}"
  style="--index: {{ block_index }}"
  {% if block_index > 0 %}
    inert
  {% endif %}
  {{ block.shopify_attributes }}
>
  <div class="layered-slideshow__panel-content">
    {%- if block.settings.toggle_overlay -%}
      {% render 'overlay', settings: block.settings %}
    {%- endif -%}
    {%- if preview_image -%}
      {%- liquid
        assign height = preview_image.width | divided_by: preview_image.aspect_ratio | round
        assign sizes = '100vw'
        assign widths = '832, 1200, 1600, 1920, 2560, 3840'
        assign loading = 'lazy'
      -%}

      {%- if block.settings.media_type_1 == 'image' -%}
        {{
          block.settings.image_1
          | image_url: width: 3840
          | image_tag: height: height, sizes: sizes, widths: widths, class: 'layered-slideshow__image', loading: loading
        }}
      {%- else -%}
        {%- if block.settings.video_1.preview_image -%}
          {{
            block.settings.video_1.preview_image
            | image_url: width: 3840
            | image_tag:
              height: height,
              sizes: sizes,
              widths: widths,
              loading: loading,
              class: 'layered-slideshow__video-poster'
          }}
        {%- endif -%}
        {{
          block.settings.video_1
          | video_tag:
            poster: null,
            autoplay: false,
            loop: true,
            controls: false,
            muted: true,
            class: 'layered-slideshow__video'
        }}
      {%- endif -%}
    {%- else -%}
      {%- liquid
        assign modulo_result = block_index | modulo: 2
        assign placeholder_variant = 2 | minus: modulo_result
        assign placeholder_name = 'hero-apparel-' | append: placeholder_variant
      -%}
      {{ placeholder_name | placeholder_svg_tag: 'layered-slideshow__image' }}
    {%- endif -%}
    <div
      class="layered-slideshow__content spacing-style{% if block.settings.background_color != blank %} color-custom-{{ block.id }}{% endif %} background-transparent"
      style="{% render 'spacing-style', settings: block.settings %}"
    >
      <div
        class="group-block-content layout-panel-flex layout-panel-flex--{{ block.settings.content_direction }}{% if block.settings.vertical_on_mobile %} mobile-column{% endif %}"
        style="{% render 'layout-panel-style', settings: block.settings %}"
      >
        {% content_for 'blocks' %}
      </div>
    </div>
  </div>
</div>

